Plan: Build a product-to-group map from columns G/H, then for each C5:C10 split on semicolons, collect unique groups, sort them ascending by group number, and write the joined result into D5:D10.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

lookup = {}
for row in vws.iter_rows(min_row=1, max_row=vws.max_row, min_col=7, max_col=8):
    code_cell, group_cell = row[0], row[1]
    if code_cell.value is not None and group_cell.value is not None:
        code = str(code_cell.value).strip()
        group = str(group_cell.value).strip()
        if code:
            lookup[code] = group

def group_sort_key(group):
    parts = group.rsplit(" ", 1)
    if len(parts) == 2 and parts[1].isdigit():
        return (0, int(parts[1]), group)
    return (1, 0, group)

for r in range(5, 11):
    raw = vws.cell(row=r, column=3).value
    groups = []

    if raw is not None:
        for part in str(raw).split(";"):
            code = part.strip()
            if code and code in lookup:
                group = lookup[code]
                if group not in groups:
                    groups.append(group)

    groups.sort(key=group_sort_key)
    result = ", ".join(groups) if groups else None

    ws.cell(row=r, column=4).value = result
    print(r, repr(raw), "->", repr(result))

wb.save(OUT)
